<?php
namespace Database\Seeders;use App\Models\{InventoryItem,LaundryService,MinibarRoomItem,Property,Room,Store};use Illuminate\Database\Seeder;
class HotelOperationsSeeder extends Seeder{public function run():void{$property=Property::query()->first();if(!$property)return;foreach([['Shirt - Wash & Iron','piece',8000,2500,24],['Trousers - Wash & Iron','piece',10000,3000,24],['Dress - Wash & Iron','piece',15000,5000,36],['Suit - Dry Clean','piece',30000,12000,48],['Bedsheet','piece',0,2500,12],['Towel','piece',0,1200,12]] as $s)LaundryService::firstOrCreate(['property_id'=>$property->id,'name'=>$s[0]],['unit'=>$s[1],'guest_price'=>$s[2],'internal_cost'=>$s[3],'turnaround_hours'=>$s[4],'is_active'=>true]);$minibarStore=Store::firstOrCreate(['property_id'=>$property->id,'code'=>'MINIBAR'],['name'=>'Mini-bar Store','type'=>'other','location'=>'Housekeeping','is_active'=>true]);$items=[];foreach([['MB-WATER','Bottled Water','beverage','bottle',3000],['MB-SODA','Soft Drink','beverage','bottle',5000],['MB-BEER','Mini-bar Beer','beverage','bottle',10000],['MB-JUICE','Juice','beverage','bottle',7000]] as $i){$item=InventoryItem::firstOrCreate(['property_id'=>$property->id,'sku'=>$i[0]],['name'=>$i[1],'kind'=>$i[2],'unit'=>$i[3],'quantity_on_hand'=>0,'reorder_level'=>10,'average_cost'=>0,'track_stock'=>true,'is_active'=>true]);$items[]=[$item,$i[4]];}foreach(Room::where('property_id',$property->id)->limit(10)->get() as $room){foreach($items as [$item,$price])MinibarRoomItem::firstOrCreate(['room_id'=>$room->id,'inventory_item_id'=>$item->id],['property_id'=>$property->id,'store_id'=>$minibarStore->id,'par_quantity'=>2,'selling_price'=>$price,'is_active'=>true]);}}
}
